import {MAPS,PET_TYPES,stats} from './engine.mjs';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export class WorldRenderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.camera={x:800,y:450};this.width=800;this.height=600;this.scale=1;this.dpr=1;this.sprites={};this.images={};this.actors=new Map;this.effects=[];this.last=0;this.map=null;this.deathScene=null;this.lastScene=null;this.lastSnapshot=-1;this.deaths=0;this.resize()}
 async load(){this.animations=await fetch('art/animations.json').then(r=>{if(!r.ok)throw Error('動畫資料載入失敗');return r.json()});const load=src=>new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('圖像載入失敗：'+src));im.src=src});await Promise.all(Object.entries(this.animations).map(async([key,a])=>this.sprites[key]=await load('art/'+a.file)));[this.images.forest,this.images.town,this.images.npcs]=await Promise.all([load('art/forest.webp'),load('assets/town.webp'),load('assets/sprites.webp')]);this.makeCrypt()}
 resize(){const b=this.canvas.getBoundingClientRect();this.width=Math.max(1,b.width);this.height=Math.max(1,b.height);this.dpr=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(this.width*this.dpr);this.canvas.height=Math.round(this.height*this.dpr);this.scale=clamp(this.width/1400,.72,1.12);this.ctx.setTransform(this.dpr,0,0,this.dpr,0,0)}
 makeCrypt(){let c=document.createElement('canvas');c.width=1600;c.height=900;const x=c.getContext('2d'),im=this.images.town;x.fillStyle='#101714';x.fillRect(0,0,1600,900);for(let y=0;y<900;y+=54)for(let z=0;z<1600;z+=90)x.drawImage(im,570,400,70,45,z,y,91,55);x.fillStyle='#111a25a0';x.fillRect(0,0,1600,900);for(const o of MAPS.crypt.obstacles){x.fillStyle='#050b0d';x.fillRect(o.x,o.y,o.w,o.h);x.strokeStyle='#55564b';x.lineWidth=7;x.strokeRect(o.x+3,o.y+3,o.w-6,o.h-6);x.strokeStyle='#292f2e';x.lineWidth=3;x.strokeRect(o.x+12,o.y+12,o.w-24,o.h-24)}this.images.crypt=c}
 screen(x,y){return{x:(x-this.camera.x)*this.scale+this.width/2,y:(y-this.camera.y)*this.scale+this.height*.46}}
 world(x,y){return{x:(x-this.width/2)/this.scale+this.camera.x,y:(y-this.height*.46)/this.scale+this.camera.y}}
 notice(events,state){const now=performance.now()/1000;for(const e of events||[]){if(['hit','critical','petHit','magic','skill'].includes(e.type)&&e.targetId){const m=state.world.monsters.find(x=>x.id===e.targetId);if(m)this.effects.push({x:m.x,y:m.y-50,start:now,text:e.damage?Math.round(e.damage):'',color:e.type==='critical'?'#e8c896':'#d8d2b4',spark:true})}if(e.type==='level')this.effects.push({x:state.player.x,y:state.player.y-90,start:now,text:'等級提升',color:'#e3ce93',long:true})}this.effects=this.effects.slice(-35)}
 actorState(id,obj,now,dt){let old=this.actors.get(id);if(!old){old={x:obj.x,y:obj.y,lastX:obj.x,lastY:obj.y,hp:obj.hp,cooldown:obj.attackCooldown||0,face:1,attackAt:-10,hitAt:-10,deathAt:-10,moving:false};this.actors.set(id,old)}let dx=obj.x-old.lastX,dy=obj.y-old.lastY;if(Math.abs(dx)>1)old.face=dx>0?1:-1;if(Math.hypot(dx,dy)>1)old.movedAt=now;old.moving=now-(old.movedAt||-10)<.3;if((obj.attackCooldown||0)>old.cooldown+.15)old.attackAt=now;if(obj.hp<old.hp)old.hitAt=now;if(obj.hp<=0&&old.hp>0)old.deathAt=now;old.x+=(obj.x-old.x)*Math.min(1,dt*17);old.y+=(obj.y-old.y)*Math.min(1,dt*17);old.lastX=obj.x;old.lastY=obj.y;old.hp=obj.hp;old.cooldown=obj.attackCooldown||0;return old}
 frameFor(type,a,now,dead){const spec=this.animations[type]||this.animations.skeleton;if(dead){let seq=spec.death;return seq[Math.min(seq.length-1,Math.floor((now-a.deathAt)*4))]??seq[0]}if(now-a.hitAt<.18)return spec.hit[0];if(now-a.attackAt<.62){let seq=spec.attack;return seq[Math.min(seq.length-1,Math.floor((now-a.attackAt)/.62*seq.length))]}if(a.moving){let seq=spec.walk;return seq[Math.floor(now*8)%seq.length]}return spec.idle[0]}
 sprite(type,frame,x,y,height=88,face=1,alpha=1){let a=this.animations?.[type],im=this.sprites[type];if(!a||!im)return;const p=this.screen(x,y),s=height/a.baseHeight*this.scale,c=this.ctx;c.save();c.globalAlpha=alpha;c.translate(p.x,p.y);c.scale(face*s,s);c.drawImage(im,frame*a.width,0,a.width,a.height,-a.anchor[0],-a.anchor[1],a.width,a.height);c.restore()}
 text(text,x,y,color='#d8d2bd',size=12){let c=this.ctx;c.font=`${size}px system-ui`;c.textAlign='center';c.textBaseline='bottom';c.lineWidth=3;c.strokeStyle='#10150dda';c.strokeText(text,x,y);c.fillStyle=color;c.fillText(text,x,y)}
 draw(state,time){const c=this.ctx,now=time/1000,dt=this.last?Math.min((time-this.last)/1000,.05):.016;this.last=time;c.setTransform(this.dpr,0,0,this.dpr,0,0);c.fillStyle='#192018';c.fillRect(0,0,this.width,this.height);if(!state){if(this.images.forest){let im=this.images.forest,sc=Math.max(this.width/im.width,this.height/im.height);c.drawImage(im,(this.width-im.width*sc)/2,(this.height-im.height*sc)/2,im.width*sc,im.height*sc);c.fillStyle='#0b140ca0';c.fillRect(0,0,this.width,this.height)}return}const live=state;if((live.summary?.deaths||0)>this.deaths&&this.lastScene&&this.lastScene.player.map!=='town'){this.deathScene={state:structuredClone(this.lastScene),at:now};this.deathScene.state.player.hp=0;}this.deaths=live.summary?.deaths||0;if(this.deathScene&&now-this.deathScene.at<1.65)state=this.deathScene.state;else{this.deathScene=null;if(now-this.lastSnapshot>.2){this.lastScene=structuredClone(live);this.lastSnapshot=now;}}const p=state.player,map=MAPS[p.map];if(this.map!==p.map){this.map=p.map;this.camera={x:p.x,y:p.y};this.actors.clear()}this.camera.x+=(p.x-this.camera.x)*Math.min(1,dt*6);this.camera.y+=(p.y-this.camera.y)*Math.min(1,dt*6);let hw=this.width/(2*this.scale),hh=this.height/(2*this.scale);if(hw<800)this.camera.x=clamp(this.camera.x,hw,1600-hw);if(hh<450)this.camera.y=clamp(this.camera.y,hh*.85,900-hh*.95);let im=this.images[p.map]||this.images.forest;if(im){c.save();c.globalAlpha=.45;let cover=Math.max(this.width/im.width,this.height/im.height);c.drawImage(im,(this.width-im.width*cover)/2,(this.height-im.height*cover)/2,im.width*cover,im.height*cover);c.restore();let o=this.screen(0,0);c.drawImage(im,o.x,o.y,1600*this.scale,900*this.scale)}
 const grad=c.createRadialGradient(this.width/2,this.height*.43,40,this.width/2,this.height*.5,Math.max(this.width,this.height)*.75);grad.addColorStop(0,'#02080300');grad.addColorStop(1,'#0209058c');c.fillStyle=grad;c.fillRect(0,0,this.width,this.height);
 if(p.moveTo){let q=this.screen(p.moveTo.x,p.moveTo.y);c.strokeStyle='#ccc49277';c.lineWidth=1;c.beginPath();c.ellipse(q.x,q.y,10,5,0,0,Math.PI*2);c.stroke()}
 const actors=[{id:'hero',kind:'hero',type:p.classId,...p},...state.world.monsters.map(m=>({...m,kind:'monster'})),...state.world.wildPets.map(a=>({...a,kind:'wild',hp:1})),...state.pets.filter(x=>x.active||x.dead).map(x=>({...x,kind:'pet'}))];
 if(p.map==='town')for(const n of map.npcs||[])actors.push({...n,kind:'npc'});
 actors.sort((a,b)=>a.y-b.y);for(const obj of actors){const a=this.actorState(obj.id,obj,now,dt),q=this.screen(a.x,a.y),dead=obj.hp<=0||obj.dead;let type=obj.type||'skeleton';if(type==='wraith')type='boss';if(type==='boar')type='spider';if(type==='goblin')type='orc';let h=obj.kind==='hero'?90:['wolf','husky','doberman'].includes(type)?54:type==='spider'?72:type==='boss'?112:86;
 if(obj.kind==='npc'){const indices={shop:6,storage:5,pet:7},rects={5:[486,357,172,294],6:[857,354,184,291],7:[1251,334,218,310]},r=rects[indices[obj.id]||6];if(this.images.npcs)c.drawImage(this.images.npcs,...r,q.x-28*this.scale,q.y-87*this.scale,56*this.scale,87*this.scale);this.text(obj.name,q.x,q.y-93*this.scale,'#d5c89a',12);continue}
 if(!dead){c.fillStyle='#15160b55';c.beginPath();c.ellipse(q.x,q.y,18*this.scale,7*this.scale,-.1,0,Math.PI*2);c.fill()}
 if(obj.kind==='hero'){c.strokeStyle='#b9b17b99';c.lineWidth=1;c.beginPath();c.ellipse(q.x,q.y,17*this.scale,7*this.scale,0,0,Math.PI*2);c.stroke()}else if(obj.id===p.targetId){c.strokeStyle='#bd705980';c.lineWidth=1.5;c.beginPath();c.ellipse(q.x,q.y,23*this.scale,9*this.scale,0,0,Math.PI*2);c.stroke()}
 const frame=this.frameFor(type,a,now,dead);this.sprite(type,frame,a.x,a.y,h,a.face,dead?.72:1);
 if(obj.kind==='hero')this.text(p.name,q.x,q.y-96*this.scale,'#dbd4b6',12);
 if(obj.kind==='pet'||obj.kind==='wild'){this.text(obj.kind==='wild'?obj.name:`${obj.name} · Lv.${obj.level}${dead?'（死亡）':''}`,q.x,q.y-(h+7)*this.scale,obj.kind==='pet'?'#bccbaa':'#c8ba92',11)}
 if(obj.kind==='monster'&&!dead&&(obj.id===p.targetId||obj.type==='boss'||obj.hp<obj.maxHp)){this.text(obj.name,q.x,q.y-(h+9)*this.scale,obj.type==='boss'?'#d5a990':'#d6cfb8',12);let w=48*this.scale,y=q.y-(h+3)*this.scale;c.fillStyle='#15130d';c.fillRect(q.x-w/2,y,w,5);c.fillStyle='#9b3c2c';c.fillRect(q.x-w/2+1,y+1,(w-2)*clamp(obj.hp/obj.maxHp,0,1),3)}
 }
 this.effects=this.effects.filter(e=>now-e.start<(e.long?2:1));for(const e of this.effects){let age=now-e.start,q=this.screen(e.x,e.y);c.save();c.globalAlpha=Math.max(0,1-age/(e.long?2:1));if(e.text)this.text(e.text,q.x,q.y-age*22,e.color,14);if(e.spark&&age<.15){c.strokeStyle='#d9c18d';c.lineWidth=1;for(let k=0;k<3;k++){let angle=k*2.1;c.beginPath();c.moveTo(q.x+Math.cos(angle)*3,q.y+35+Math.sin(angle)*3);c.lineTo(q.x+Math.cos(angle)*9,q.y+35+Math.sin(angle)*9);c.stroke()}}c.restore()}
 }
 hitTest(state,x,y){const p=this.world(x,y),near=(a,r)=>Math.hypot(a.x-p.x,(a.y-30)-p.y)<r/this.scale;let monsters=state.world.monsters.filter(a=>a.hp>0&&near(a,43)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));if(monsters[0])return{kind:'monster',entity:monsters[0]};let wild=state.world.wildPets.find(a=>near(a,39));if(wild)return{kind:'wild',entity:wild};if(state.player.map==='town'){let npc=(MAPS.town.npcs||[]).find(a=>near(a,45));if(npc)return{kind:'npc',entity:npc}}return{kind:'ground',x:p.x,y:p.y}}
}
